pub extern "C" fn xmlParserGrow(mut ctxt: xmlParserCtxtPtr) -> c_int { unsafe {
    let mut in_0: xmlParserInputPtr = (*ctxt).input;
    let mut buf: xmlParserInputBufferPtr = (*in_0).buf;
    let mut curEnd: ptrdiff_t = (*in_0).end.offset_from((*in_0).cur) as ptrdiff_t;
    let mut curBase: ptrdiff_t = (*in_0).cur.offset_from((*in_0).base) as ptrdiff_t;
    let mut ret: c_int = 0;
    if buf.is_null() {
        return 0 as c_int;
    }
    if (*ctxt).progressive != 0 && (*ctxt).inputNr <= 1 as c_int {
        return 0 as c_int;
    }
    if (*buf).encoder.is_null() && (*buf).readcallback.is_none() {
        return 0 as c_int;
    }
    if (*buf).error != 0 as c_int {
        return -(1 as c_int);
    }
    if (curEnd > XML_MAX_LOOKUP_LIMIT as ptrdiff_t || curBase > XML_MAX_LOOKUP_LIMIT as ptrdiff_t)
        && (*ctxt).options & XML_PARSE_HUGE as c_int == 0 as c_int
    {
        xmlErrMemory(
            ctxt,
            b"Huge input lookup\0" as *const u8 as *const c_char,
        );
        xmlHaltParser(ctxt);
        return -(1 as c_int);
    }
    if curEnd >= INPUT_CHUNK as ptrdiff_t {
        return 0 as c_int;
    }
    ret = xmlParserInputBufferGrow(buf, INPUT_CHUNK);
    xmlBufUpdateInput((*buf).buffer, in_0, curBase as size_t);
    if ret < 0 as c_int {
        xmlFatalErr(
            ctxt,
            (*buf).error as xmlParserErrors,
            ::core::ptr::null::<c_char>(),
        );
        if (*buf).error == XML_ERR_NO_MEMORY as c_int {
            xmlHaltParser(ctxt);
        }
    }
    return ret;
} }
